   "resumen": "Los pedidos y planteamientos presentados por más de 45 organizaciones durante la audiencia pública de diputados y senadores de Juntos por el Perú, desarrollada el último viernes en Puno, no deben quedarse únicamente en una recopilación de demandas, sino pasar a mesas de trabajo…",
   "fuente": "El Búho",
   "url": "https://elbuho.pe/2026/11/exdirigente-de-autoridades-originarias-piden-resultados-concretos-tras-audiencia-de-juntos-por-el-peru-en-puno/",
