   "ambito": "mundo",
   "procedencia": "directa",
   "sintesis": "Con mayoría en ambas cámaras a partir de enero, los legisladores impulsan una vía a la ciudadanía para millones de indocumentados y se dividen entre reformar y eliminar el ICE Hace apenas unos meses parecía impensable siquiera comenzar a discutir un plan para legalizar a más de diez millones de indocumentados y, con posibilidades reales de concretarlo, plantear reformas o incluso la eliminación del Servicio de Inmigración y Control de Aduanas (ICE, por sus siglas en inglés).",
   "puntos": [
    "Con mayoría en ambas cámaras a partir de enero, los legisladores impulsan una vía a la ciudadanía para millones de indocumentados y se dividen entre reformar y eliminar el ICE",
    "Hace apenas unos meses parecía impensable siquiera comenzar a discutir un plan para legalizar a más de diez millones de indocumentados y, con posibilidades reales de concretarlo, plantear reformas o incluso la eliminación del Servicio de Inmigración y Control de Aduanas (ICE, por sus siglas en inglés).",
    "Mientras sus agentes desplegaban operativos en vecindarios hispanos y la violencia de sus acciones alcanzaba su punto más crítico con la muerte a tiros de migrantes y ciudadanos, los legisladores demócratas concentraban sus reclamos en frenar a la agencia y exigir mejores condiciones en los centros de detención."
   ]
